function productGrid(){
  const q=normalize(filters.q),sharing=location.hash.startsWith('#/compartir');
  const list=products.filter(p=>(filters.category==='Todas'||(filters.category==='Material para socios'?['HERRAMIENTAS','PUBLICITARIOS'].includes(p.category):p.category===filters.category))&&normalize(`${p.name} ${p.presentation}`).includes(q));
  return `<p class="muted results-count" role="status">${list.length} productos · Precio público en MXN</p><div class="grid products-grid">${list.map(p=>`<article class="card product"><div class="product-img">${p.image?`<img src="${p.image}" alt="${esc(p.name)}" loading="lazy">`:'<span class="no-photo">Imagen no disponible</span>'}</div><div class="product-info"><span class="tag">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p class="muted product-presentation">${esc(p.presentation)}</p><p class="product-hook">${esc(productDescription(p)?.hook||'Conoce esta presentación Bio4.')}</p><div class="price">${money(p.price)}</div><div class="product-actions">${link(`productos/${p.id}`,'Ver producto','btn secondary')}${sharingEligibility(p).enabled?link(`compartir/${p.id}`,'Compartir','btn share') : ''}</div></div></article>`).join('')}</div>${!list.length?'<div class="card empty"><h3>No encontramos coincidencias</h3><p>Prueba con otro nombre o cambia la categoría.</p><button class="btn secondary" data-action="reset-products">Limpiar filtros</button></div>':''}`;
}
function catalog(){
  const sharing=location.hash.startsWith('#/compartir');
  const categories=[['Todas','Todos'],['SUPLEMENTOS','Suplementos'],['ALIMENTOS','Alimentos'],['CUIDADO PERSONAL','Cuidado personal'],['ECOLOGÍA','Ecología'],['Material para socios','Material para socios']];
  return heading(sharing?'ELIGE UN PRODUCTO':'CONOCE · COMPARTE',sharing?'Compartir':'Productos',sharing?'Encuentra el producto y prepara un texto para Catálogo, Estado o Chat.':'Busca por nombre o explora una categoría.')+`<div class="toolbar"><div class="search"><label for="product-search">Buscar producto</label><input type="search" id="product-search" placeholder="Nombre o presentación…" value="${esc(filters.q)}"></div></div><div class="category-chips" role="group" aria-label="Categorías de productos">${categories.map(([value,label])=>`<button class="category-chip ${value===filters.category?'active':''}" data-category="${esc(value)}" aria-pressed="${value===filters.category}">${label}</button>`).join('')}</div><div id="product-results">${productGrid()}</div><p class="smallprint">Precios de la base Bio4 2026, revisión del 16 de septiembre. Confirma el total y las condiciones antes de acordar un pedido.</p>`;
}

let shareStage='catalogo',shareVariant='A',followReply='info';
const shareDrafts=new Map();
const shareKey=p=>[db.current,p.id,shareStage,shareVariant].join(':');
function shareText(p){return shareDrafts.get(shareKey(p))??makeShareCopy(p,shareStage,shareVariant);}
export function publicCopy(p,kind){return makeShareCopy(p,kind==='estado'?'interes':kind==='whatsapp'?'informacion':kind,shareVariant);}
function sharePolicy(){return '<details style="margin-top:18px"><summary>Cómo compartir con respeto</summary><p>Escribe solo a quien pidió información o aceptó recibir tus mensajes. Ver un Estado no es aceptar promociones. Respeta las bajas y no uses envíos masivos no autorizados. La política oficial restringe el marketing multinivel y ciertos productos de salud. Un borrador factual no autoriza su uso en tu cuenta; revisa el producto y el canal antes de publicarlo o enviarlo.</p><p>Las plantillas aprobadas y la ventana de 24 horas corresponden a la Plataforma/API. Esta app solo prepara texto; no envía mensajes.</p><a href="https://business.whatsapp.com/policy" target="_blank" rel="noopener">Consultar política oficial de WhatsApp</a></details>';}
function shareResults(p){const ev=db.events.filter(e=>e.user===db.current);const rows=summarizeShareResults(ev,p.id);const last=ev.filter(e=>e.type==='share_outcome'&&e.item===p.id).at(-1);return `<details style="margin-top:24px"><summary>Prueba A/B · mis resultados de los últimos 7 días</summary><p class="smallprint">Registro manual de este socio y navegador. Copiar no cuenta como respuesta ni venta. Registra cada respuesta, consulta o pedido una sola vez; una conversación puede avanzar por varias etapas. No son personas únicas ni una tasa de conversión.</p><div style="overflow-x:auto"><table style="width:100%;text-align:left"><caption class="sr-only">Resultados manuales por variante</caption><thead><tr><th>Variante</th><th>Respuestas</th><th>Consultas</th><th>Pedidos</th></tr></thead><tbody>${Object.entries(rows).map(([v,r])=>`<tr><th>${v}</th><td>${r.response}</td><td>${r.inquiry}</td><td>${r.order}</td></tr>`).join('')}</tbody></table></div><p>Registrar para <strong>${shareVariant}</strong>:</p><div class="flex">${[['response','Respuesta recibida'],['inquiry','Consulta del producto'],['order','Pedido confirmado']].map(([id,label])=>`<button class="btn secondary small" data-share-outcome="${id}">${label}</button>`).join('')}</div>${last?`<button class="btn ghost small" data-share-undo="${last.id}">Deshacer último registro</button>`:''}<p class="smallprint">Compara variantes con un número parecido de publicaciones o conversaciones autorizadas. No vuelvas a escribirle a la misma persona solo para probar un texto.</p></details>`;}
function sharingPanel(p){const eligibility=sharingEligibility(p);if(!eligibility.enabled)return `<span class="eyebrow">COMPARTIR CON CRITERIO</span><h2>Revisar este producto antes de promocionar</h2><p>${esc(eligibility.reason)}</p><button class="btn secondary" data-tab="aprender">Consultar ficha e ingredientes</button>${sharePolicy()}`;return `<span class="eyebrow">UNA CONVERSACIÓN, UN SIGUIENTE PASO</span><h2>Prepara tu mensaje</h2><p class="muted">Elige dónde lo compartirás. A abre con una necesidad cotidiana; B va directo al producto. Catálogo explica, Estado despierta interés y Chat responde con más detalle. Precio, pedido y seguimiento van al paso correspondiente. Puedes editar cada texto.</p><div class="share-channels" role="group" aria-label="Formato para compartir">${shareStages.slice(0,3).map(([v,t])=>`<button class="btn ${v===shareStage?'':'secondary'} small" data-share-stage="${v}" aria-pressed="${v===shareStage}">${t}</button>`).join('')}</div><div class="field" style="margin-top:18px"><label for="share-stage">Otros mensajes</label><select id="share-stage" style="width:100%"><option value="" ${shareStages.slice(0,3).some(s=>s[0]===shareStage)?'selected':''}>Precio, pedido o seguimiento</option>${shareStages.slice(3).map(([v,t])=>`<option value="${v}" ${v===shareStage?'selected':''}>${t}</option>`).join('')}</select></div><div class="share-variants" role="group" aria-label="Variante del mensaje">${['A','B'].map(v=>`<button class="btn ${v===shareVariant?'':'secondary'}" data-share-variant="${v}" aria-pressed="${v===shareVariant}">Variante ${v}</button>`).join('')}</div><p class="smallprint">${shareStages.find(s=>s[0]===shareStage)[2]}</p><label for="share-editor">Vista previa · puedes editarla antes de copiar</label><textarea id="share-editor" class="share-editor" rows="12" maxlength="1500" style="width:100%;resize:vertical;margin-top:10px" aria-describedby="share-review">${esc(shareText(p))}</textarea><p id="share-count" class="smallprint">${shareText(p).length}/1500 caracteres</p><div id="share-review" role="status">${shareReview(shareText(p))}</div><div class="flex"><button class="btn share-copy-btn" data-action="copy-share">📋 Copiar mensaje</button><button class="btn ghost small" data-action="reset-share">Restaurar esta variante</button></div><p class="smallprint">Los borradores se conservan en esta pestaña mientras la mantengas abierta. ${esc(eligibility.reason)} Los precios corresponden a la base publicada; confirma vigencia y entrega antes del pedido.</p>${sharePolicy()}${shareResults(p)}`;}
function shareReview(text){const issues=shareTextIssues(text);return issues.length?`<div class="notice">${issues.map(esc).join('<br>')}</div>`:'<p class="smallprint">Revisa que cada afirmación sea verdadera. Este aviso es orientativo: no certifica cumplimiento ni detecta todos los riesgos.</p>';}
function currentProduct(){return products.find(p=>p.id===location.hash.split('/')[2]);}
function mushroomLearning(p){if(!/ganoderma|shiitake|hericium|melena de le[oó]n/i.test(p.ingredients||''))return '';return '<details style="margin:20px 0"><summary>Hongos y adaptógenos · aprende a explicarlos</summary><p>“Adaptógeno” se usa para describir sustancias estudiadas por su posible relación con la respuesta al estrés. No es una propiedad automática de todos los hongos ni demuestra que un producto comercial produzca ese efecto.</p><p>Ganoderma lucidum (reishi), shiitake y melena de león son hongos distintos. Explica cuál figura en la etiqueta. Los resultados de un extracto o de una mezcla no se trasladan sin más a otra dosis, presentación o cosmético.</p><p>Para compartir, destaca los ingredientes declarados y los beneficios específicos respaldados de la fórmula; no prometas efectos sobre el estrés, las defensas o las enfermedades por contener hongos.</p><a href="https://www.mskcc.org/cancer-care/integrative-medicine/herbs/reishi-mushroom" target="_blank" rel="noopener">Consultar evidencia y precauciones del reishi · MSK</a></details>';}
function mediaPanel(p){const cards=productMedia[p.id]||[];return `<aside class="card">${p.image?`<img class="detail-img" src="${p.image}" alt="${esc(p.name)}"><p class="smallprint">Imagen de referencia. Consulta la presentación indicada en la ficha.</p>`:'<div class="product-img"><span class="no-photo">Imagen no disponible</span></div>'}<h3>${esc(p.name)}</h3><p class="muted">${esc(p.presentation)}</p><div class="metric" style="font-size:30px">${money(p.price)}</div>${p.image?`<div class="image-actions"><button class="btn secondary" data-share-image="${p.image}">Fotos / compartir</button><a class="btn ghost" href="${p.image}" target="_blank" rel="noopener">Abrir imagen</a></div>`:''}${cards.length?`<h3 class="media-heading">Tarjetas originales para compartir</h3><p class="smallprint">Estas imágenes conservan el texto original de Bio4; algunas afirmaciones difieren de la ficha actual. Comprueba la presentación y la información vigente antes de enviarlas.</p><div class="media-grid">${cards.map(c=>`<figure class="media-card"><img src="${c.src}" alt="${esc(c.label)} de ${esc(p.name)}" loading="lazy"><figcaption><strong>${esc(c.label)}</strong><button class="btn secondary small" data-share-image="${c.src}">Fotos / compartir</button><a class="btn ghost small" href="${c.src}" target="_blank" rel="noopener">Abrir</a></figcaption></figure>`).join('')}</div>`:''}${p.id==='B4-CEUTICA4-01'?'<p class="notice">La imagen histórica muestra tres sabores. Chocolate y Vainilla siguen en reformulación; consulta únicamente la presentación Natural.</p>':''}${p.image||cards.length?'<p class="smallprint">En iPhone, usa «Fotos / compartir» y elige Guardar imagen en la hoja del sistema. Si no aparece, abre la imagen y mantén presionada la foto. «Descargar» en Safari suele guardarla en Archivos.</p>':''}</aside>`;}
function detail(id){const p=products.find(p=>p.id===id);if(!p)return heading('PRODUCTOS','No encontramos ese producto')+link('productos','Volver al catálogo');const description=productDescription(p);return `${link(location.hash.startsWith('#/compartir/')?'compartir':'productos',location.hash.startsWith('#/compartir/')?'← Compartir':'← Productos','btn ghost small')}${heading(esc(p.category),esc(p.name),esc(p.presentation))}${favoriteButton(user(),'producto',p.id,esc)}<div class="split"><section class="card"><div class="tabs" aria-label="Información del producto"><button class="btn secondary" data-tab="aprender" aria-pressed="${detailTab==='aprender'}">Aprender</button><button class="btn secondary" data-tab="compartir" aria-pressed="${detailTab==='compartir'}">Compartir</button></div>${detailTab==='aprender'?`<span class="eyebrow">PARA CONOCER EL PRODUCTO</span>${description?`<div class="product-description"><h2>${esc(description.hook)}</h2><p>${esc(description.body)}</p><p class="smallprint">📦 ${esc(p.presentation)} · Precio público: ${money(p.price)}.</p>${description.review.length?`<p class="smallprint">Por revisar: ${esc(description.review.join(' '))}</p>`:''}<p><strong>¿Te interesa?</strong> Consulta disponibilidad y entrega.</p></div>`:''}<h2 style="margin-top:16px">Los datos esenciales</h2><p><strong>Presentación:</strong> ${esc(p.presentation)}<br><strong>Precio público:</strong> ${money(p.price)}</p>${p.ingredients?`<h3>Ingredientes destacados</h3><p>${esc(p.ingredients)}</p><p class="smallprint">Ingredientes destacados del catálogo del fabricante; consulta la etiqueta para la lista completa.</p>`:'<p>Para conocer la composición y las indicaciones de esta presentación, revisa su etiqueta con tu asesor.</p>'}${mushroomLearning(p)}${p.benefits?.length?`<h3>Beneficios</h3><ul class="benefits-list">${p.benefits.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><p class="smallprint">Beneficios generales de bienestar; no son promesas de resultado individual. Este producto no está destinado a diagnosticar, tratar, curar ni prevenir ninguna enfermedad. Ante cualquier condición de salud, consulta a un profesional médico.</p>`:''}<div class="notice">Pregunta qué busca la persona antes de recomendar. Explica los datos del producto sin prometer resultados individuales.</div><button class="btn" data-tab="compartir">Ver textos para compartir →</button>`:sharingPanel(p)}</section>${mediaPanel(p)}</div>`;}
function more(){
  const items=[['campanas','◧','Mis campañas','Preparar contenido para Meta, Instagram, Facebook, WhatsApp y TikTok.'],['retos','◈','Retos de práctica','Producto, objeción y Estado con reflexión.'],['respaldo','↓','Guardar y recuperar mi avance','Lleva tu progreso a otro teléfono.'],['historia','✎','Mi historia en un minuto','Tu presentación personal, paso a paso.'],['favoritos','★','Mis favoritos','Productos, respuestas y videos guardados.'],['lecturas','▤','Lecturas recomendadas','Diez libros en español para aprender y aplicar.'],['semana','◷','Mi semana','Mis tres tareas, fechas y revisión semanal.'],['secuencia','✦','Mi Secuencia Mágica','Tu sistema de ocho pasos para aprender y actuar.'],['avance','◫','Mi avance','Lo hecho, lo pendiente y tu siguiente paso.'],['plan','▣','Plan de 7 pasos','Elige una ruta de inicio o de equipo.'],['estados','▣','Mi primer Estado','Texto, imagen y respuesta a preguntas.'],['aprender','▤','Aprender','Tu ruta de socio nuevo.'],['videos','▶','Videos útiles','Capacitación Bio4 y tutoriales de WhatsApp.'],['guias','◇','Guías de conversación','Preguntas y siguientes pasos, uno a la vez.'],['equipo','✦','Equipo','Acompaña a un socio nuevo paso a paso.'],['objeciones','☏','Objeciones','Respuestas a preguntas frecuentes.'],['cierres','✓','Cierres','Siguientes pasos sin presión.'],['oportunidad','↗','Oportunidad Bio4','Conoce el negocio.'],['seguimientos','◷','Seguimientos','Retoma conversaciones acordadas.'],['buzon','✉','Buzón de mejoras','Comparte una idea o reporta algo que pasó.']];
  return heading('TODAS TUS HERRAMIENTAS','Más opciones','Entra directamente a lo que necesitas.')+`<div class="more-list">${items.map(([route,icon,title,desc])=>`<a class="more-item" href="#/${route}"><span class="more-icon" aria-hidden="true">${icon}</span><span><strong>${title}</strong><small>${desc}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div>`;
}
function messageCoachForm(){
  return `<section class="card message-coach"><span class="eyebrow">PRACTICA CON TUS PALABRAS</span><h2>Revisa un mensaje antes de usarlo</h2><p class="muted">Escribe un borrador. Recibirás observaciones concretas para hacerlo más claro y respetuoso.</p><form id="message-coach"><div class="field"><label for="coach-context">¿Cómo comenzó la conversación?</label><select id="coach-context" name="context"><option value="sin_acuerdo">Aún no aceptó recibir información</option><option value="consulta">La persona me escribió primero</option><option value="acordado">Acordamos que le enviaría información o retomaría el tema</option></select></div><div class="field"><label for="coach-draft">Tu borrador</label><textarea id="coach-draft" name="draft" rows="5" minlength="12" maxlength="1500" required placeholder="Escribe aquí como se lo dirías tú…"></textarea></div><button class="btn" type="submit">Revisar mi mensaje →</button></form><div id="coach-results" class="coach-results" role="status" aria-live="polite"></div><p class="smallprint">El borrador se revisa en este navegador y no se guarda ni se envía. Esta herramienta detecta algunas señales de redacción; no comprueba permisos, precios, beneficios ni cumplimiento.</p></section>`;
}
function messageCoachFeedback(result){
  return `<h3>Qué puedes mejorar</h3><p>${esc(result.intro)}</p>${result.checks.length?`<ul class="coach-checks">${result.checks.map(item=>`<li class="coach-check ${['good','review','neutral'].includes(item.kind)?item.kind:'neutral'}"><strong>${esc(item.title)}</strong><span>${esc(item.body)}</span></li>`).join('')}</ul>`:''}${result.next?`<p class="coach-next"><strong>Próximo paso:</strong> ${esc(result.next)}</p>`:''}`;
}
document.addEventListener('submit',e=>{
  if(e.target.id!=='message-coach')return;
  e.preventDefault();
  const data=new FormData(e.target);
  const feedback=reviewMessageDraft(data.get('draft'),data.get('context'));
  $('#coach-results').innerHTML=messageCoachFeedback(feedback);
  $('#coach-results').scrollIntoView({behavior:'smooth',block:'nearest'});
});
function guidesPage(){
  return heading('VENDER CON AYUDA','Guías de conversación','Elige el momento en que estás. Toma una pregunta útil, escucha la respuesta y decide el siguiente paso sin presión.')+
    messageCoachForm()+
    `<nav class="guide-jumps" aria-label="Ir a un paso de conversación">${conversationGuides.map(g=>`<button type="button" data-guide-jump="${g.id}">${g.step} · ${g.short}</button>`).join('')}</nav><div class="guide-list">${conversationGuides.map(g=>`<article class="card guide-card" id="guia-${g.id}"><div class="guide-head"><span class="guide-step">${g.step}</span><div><span class="eyebrow">CUÁNDO USARLA</span><h2>${g.title}</h2><p class="muted">${g.moment}</p></div></div><div class="guide-details"><div class="guide-prompt"><span class="eyebrow">PREGUNTA ÚTIL</span><p>${g.ask}</p></div><div><strong>Escucha</strong><p>${g.listen}</p></div><div><strong>Evita</strong><p>${g.avoid}</p></div><div><strong>Siguiente paso</strong><p>${g.next}</p></div></div><button class="btn secondary" data-start="${g.practice}">Practicar un caso relacionado →</button></article>`).join('')}</div><div class="notice">Estas guías no envían mensajes. En WhatsApp, conversa solo con personas que aceptaron recibir información y respeta si no desean continuar. <a href="https://business.whatsapp.com/policy/preview?lang=es_LA" target="_blank" rel="noopener">Consulta la política de WhatsApp Business</a>.</div>`;
}
function teamPage(){
  const done=Array.isArray(user().teamSteps)?user().teamSteps:[];
  return heading('LIDERAZGO PRÁCTICO','Acompaña a un socio paso a paso','Una ruta breve para enseñar, escuchar y practicar juntos. Cada persona avanza a su ritmo.')+
    `<section class="card team-progress"><div class="flex"><div><h2>Tu ruta de acompañamiento</h2><p class="muted">${done.length} de ${teamSteps.length} pasos revisados en este navegador.</p></div><span class="spacer"></span><span class="tag">${Math.round(done.length/teamSteps.length*100)}% revisado</span></div><div class="progress" role="progressbar" aria-label="Pasos de acompañamiento revisados" aria-valuenow="${done.length}" aria-valuemin="0" aria-valuemax="${teamSteps.length}"><span style="width:${done.length/teamSteps.length*100}%"></span></div><p class="smallprint">Marcar un paso solo registra tu revisión; no confirma conversaciones, ventas ni resultados de otros socios.</p></section>`+
    `<div class="team-list">${teamSteps.map((step,i)=>`<article class="card team-card"><div class="team-head"><span class="team-number">${i+1}</span><div><h2>${esc(step.title)}</h2><p>${esc(step.task)}</p></div></div><div class="team-question"><span class="eyebrow">PREGUNTA PARA CONVERSAR</span><p>${esc(step.question)}</p></div><p class="smallprint"><strong>Cuida esto:</strong> ${esc(step.avoid)}</p><div class="team-actions">${link(step.route,step.action+' →','btn secondary')}<label><input class="check" type="checkbox" data-team-step="${i}" ${done.includes(i)?'checked':''}> Revisé este paso</label></div></article>`).join('')}</div>`+
    `<div class="notice">Esta ruta es para formación interna. Las actividades y el progreso se guardan solo en este dispositivo; no muestran resultados del equipo ni sustituyen el plan oficial vigente de Bio4.</div>`;
}
function library(kind){const data=kind==='objeciones'?objections:closings;return heading(kind==='objeciones'?'ESCUCHA ANTES DE RESPONDER':'AVANZA CON PERMISO',kind==='objeciones'?'Objeciones':'Cierres sin presión',kind==='objeciones'?'Una duda es una oportunidad para entender mejor.':'Ayuda a decidir con claridad, incluso cuando la respuesta sea «no».')+`<div class="grid">${data.map(o=>`<article class="card"><span class="tag">${kind==='objeciones'?'Objeción':'Siguiente paso'}</span><h3 style="margin-top:16px">${esc(o.title)}</h3><p class="muted" style="font-size:14px">${esc(o.learn)}</p>${favoriteButton(user(),kind,o.id,esc)}<button class="btn secondary" data-open-response="${kind}:${o.id}">Ver respuesta</button></article>`).join('')}</div>`;}
function responseDialog(kind,id){const o=(kind==='objeciones'?objections:closings).find(o=>o.id===id);if(!o)return;if(['negocio','oportunidad'].includes(o.id)){modal(`<h2>${esc(o.title)}</h2><p>${esc(o.learn)}</p><p>Contenido para aprender. No preparamos invitaciones ni promoción de multinivel para WhatsApp.</p>`);return;}event(kind==='objeciones'?'objection_viewed':'closing_viewed',{item:id});modal(`<span class="eyebrow">APRENDER</span><h2 style="margin-top:12px">${esc(o.title)}</h2><p class="muted">${esc(o.learn)}</p><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><span class="eyebrow">COMPARTIR</span><div class="copy-box">${esc(o.text)}</div>${copyButton(o.text,kind==='objeciones'?'response_copied':'closing_copied',id)}`);}
function videosPage(){
  const cards=videos=>`<div class="video-list">${videos.map((video,i)=>`<article class="card video-card" id="video-${video.id}"><div class="video-head"><span class="video-number">${i+1}</span><div><span class="eyebrow">${esc(video.source)}</span><h2>${esc(video.title)}</h2></div></div><p>${esc(video.description)}</p>${favoriteButton(user(),'video',video.id,esc)}<div class="video-frame" data-video-frame="${video.id}"><button class="video-play" type="button" data-play-video="${video.id}" aria-label="Reproducir ${esc(video.title)} aquí"><span aria-hidden="true">▶</span><strong>Ver video aquí</strong></button></div><p class="video-action"><strong>Después de verlo:</strong> ${esc(video.action)}</p><div class="video-links"><a class="btn secondary" href="https://www.youtube.com/watch?v=${video.id}" target="_blank" rel="noopener">Abrir en YouTube ↗</a>${link(video.route,esc(video.button)+' →','btn ghost')}</div></article>`).join('')}</div>`;
  return heading('MIRA · PRUEBA · PRACTICA','Videos útiles','Aprende una idea y aplícala en tu trabajo diario.')+
    `<div class="notice">Las charlas de Bio4 son material de capacitación externo. Ver un video no valida precios, afirmaciones sobre productos o resultados de negocio. Comprueba la información vigente antes de compartirla. Los tutoriales de WhatsApp muestran pantallas que pueden haber cambiado.</div>`+
    `<div class="plan-switch" role="group" aria-label="Temas de video">${['Todos',...videoCategories].map(t=>`<button class="btn ${videoTopic===t?'':'secondary'}" data-video-topic="${esc(t)}" aria-pressed="${videoTopic===t}">${esc(t)}</button>`).join('')}</div>`+
    videoCategories.filter(t=>videoTopic==='Todos'||videoTopic===t).map(t=>`<div class="section-line"><h2>${esc(t)}</h2><span class="tag">${learningVideos.filter(v=>videoCategory(v)===t).length} videos</span></div>${cards(learningVideos.filter(v=>videoCategory(v)===t))}`).join('')+
    `<p class="smallprint">Reproducir un video carga el reproductor de YouTube. La webapp no registra lo que ves ni marca una lección como completada.</p>`;
}
function learn(){const done=user().lessons;return `<div class="card"><h2>Lee una idea y ponla en práctica</h2><p>Diez libros en español para tu formación en mercadeo en red, con un motivo para leer cada uno.</p>${link('lecturas','Explorar lecturas recomendadas →','btn secondary')}</div>`+heading('RUTA DE SOCIO NUEVO','Tu primer paso cuenta','Aprende, ponlo en práctica y marca cada paso cuando lo hayas hecho.')+`<div class="card" style="margin-bottom:24px"><div class="flex"><h3 style="margin:0">Tu avance</h3><span class="spacer"></span><span>${done.length} de 6</span></div><div class="progress"><span style="width:${done.length/6*100}%"></span></div></div><div class="card learn-video-callout"><div><span class="eyebrow">APRENDE VIÉNDOLO</span><h2>Videos de Bio4 y WhatsApp Business</h2><p>Conoce la tienda virtual y practica herramientas para conversar con tus clientes.</p></div>${link('videos','Ver videos útiles →','btn secondary')}</div>${lessons.map((l,i)=>`<section class="card step ${done.includes(i)?'completed':''}"><div class="step-number">${done.includes(i)?'✓':i+1}</div><div><h3>${l.title}</h3><p class="muted">${l.body}</p>${link(l.route,l.action+' →','btn ghost small')}<label class="flex" style="margin-top:16px;font-weight:400"><input type="checkbox" class="check" data-lesson="${i}" ${done.includes(i)?'checked':''}> ${l.task}</label></div></section>`).join('')}`;}
function practiceList(){const active=user().practice,exam=user().exam;const list=scenarios.filter(s=>practiceFilters.topic==='Todos'||s.topic===practiceFilters.topic);return heading('TU ESPACIO PARA ENSAYAR','Simulador de Prospectos','Responde con tus propias palabras. Hay muchas formas de llevar una buena conversación.')+`${active?`<div class="notice flex"><div>Tienes una conversación ${active.completed?'terminada':'en curso'} con ${scenarios.find(s=>s.id===active.scenario).person}.</div><span class="spacer"></span>${link('sesion',active.completed?'Ver retroalimentación':'Continuar práctica','btn secondary')}</div>`:''}${exam?.completed?link('examen','Ver mi último examen →','btn ghost small'):''}<section class="card"><div class="flex"><div><h3>Elige cómo practicar</h3><p class="muted" style="margin:0">30 escenarios · Tres dificultades · Respuestas libres</p></div><span class="spacer"></span><button class="btn secondary" data-action="exam">${exam&&!exam.completed?'Continuar examen':exam?.completed?'Nuevo examen de 10':'Examen de 10 situaciones'}</button></div><div class="toolbar"><div><label for="difficulty">Dificultad</label><select id="difficulty">${difficulties.map(d=>`<option ${practiceFilters.difficulty===d?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="topic">Situación</label><select id="topic"><option value="Todos">Todas las situaciones</option>${Object.entries(topics).map(([k,v])=>`<option value="${k}" ${practiceFilters.topic===k?'selected':''}>${v}</option>`).join('')}</select></div></div><p class="smallprint" style="margin:0">Nuevo: 3 rondas, prospecto receptivo. Intermedio: 4 rondas con dudas. Difícil: 5 rondas y objeciones combinadas.</p></section><div class="section-line"><h2>Elige tu conversación</h2><span class="tag">${list.length} escenarios</span></div><div class="grid">${list.map(s=>`<article class="card"><div class="flex"><span class="tag">${topics[s.topic]}</span><span class="spacer"></span><span class="muted" style="font-size:12px">${s.id.replace('s','#')}</span></div><h3 style="margin-top:18px">${s.title}</h3><p class="muted" style="font-size:14px">${s.person} · ${s.context}</p><p>“${s.opening}”</p><button class="btn secondary" data-start="${s.id}">Practicar →</button></article>`).join('')}</div><p class="smallprint">Simulador local basado en escenarios y señales del texto. La retroalimentación es orientativa: no certifica habilidades ni verifica la exactitud de cada afirmación.</p>`;}
function createPractice(id,exam=false){const s=scenarios.find(s=>s.id===id);if(!s)return;const diff=exam?user().exam.difficulty:practiceFilters.difficulty;user().practice={id:uid(),scenario:id,difficulty:diff,responses:[],messages:[{role:'prospect',text:s.opening}],completed:false,exam,started:new Date().toISOString()};event('practice_started',{scenario:id,difficulty:diff,mode:exam?'exam':'practice',practice:user().practice.id});sessionDraft='';navigate('sesion');}
function startPractice(id){const old=user().practice;if(user().exam&&!user().exam.completed){modal('<h2>Hay un examen en curso</h2><p>Termina o abandona el examen antes de empezar una práctica independiente.</p><button class="btn" data-action="exam">Continuar examen</button>');return;}if(old&&!old.completed){modal('<h2>¿Empezar otra conversación?</h2><p>La práctica actual quedará sin completar. Tu progreso de aprendizaje se conserva.</p><button class="btn" data-replace="'+id+'">Empezar esta práctica</button>');return;}createPractice(id);}
function session(){const p=user().practice;if(!p)return heading('PRACTICAR','Elige una conversación para comenzar')+link('practicar','Ver escenarios');const s=scenarios.find(s=>s.id===p.scenario);if(p.completed)return results(p);return `${link('practicar','← Escenarios','btn ghost small')}${heading(p.exam?`EXAMEN · SITUACIÓN ${user().exam.index+1} DE 10`:'PRÁCTICA LIBRE',s.title)}<div class="split"><section class="card"><div class="flex" style="border-bottom:1px solid var(--line);padding-bottom:16px"><span class="avatar">${s.person[0]}</span><div><strong>${s.person}</strong><div class="muted" style="font-size:13px">Prospecto simulado</div></div><span class="spacer"></span><span class="tag">${p.difficulty} · ${p.responses.length}/${roundCount(p.difficulty)} rondas</span></div><div class="chat" role="log" aria-label="Conversación con el prospecto">${p.messages.map(m=>`<div class="message ${m.role==='user'?'mine':''}"><small>${m.role==='user'?'Tú':s.person}</small>${esc(m.text)}</div>`).join('')}</div><form id="answer"><label for="reply">Tu respuesta</label><textarea id="reply" name="reply" rows="3" required minlength="12" maxlength="1500" placeholder="Escucha, pregunta y responde con tus palabras…">${esc(sessionDraft)}</textarea><div class="flex" style="margin-top:12px"><span class="muted" style="font-size:13px">Mínimo 12 caracteres · Sin respuesta única</span><span class="spacer"></span><button class="btn" type="submit">Enviar respuesta →</button></div></form></section><aside><div class="card"><span class="eyebrow">CONOCE A TU PROSPECTO</span><h3 style="margin-top:14px">${s.person}</h3><p>${s.context}</p><span class="tag">${topics[s.topic]}</span></div>${!p.exam?`<div class="card" style="margin-top:16px"><h3>Tu objetivo</h3><p class="muted">${esc(practiceGoal(s))}</p><p class="smallprint">No necesitas convencer a toda costa. Aceptar un «no» también es avanzar.</p></div>`:''}<button class="btn ghost small" style="margin-top:14px" data-action="abandon">${p.exam?'Abandonar examen':'Terminar sin completar'}</button></aside></div>`;}
function resultBars(r){return dimensions.map((d,i)=>`<div class="score-row"><strong>${d}</strong><span>${r.scores[i]}/100</span></div><div class="progress"><span style="width:${r.scores[i]}%"></span></div><p class="muted" style="font-size:14px">${r.feedback[i]}</p>`).join('');}
function results(p){const s=scenarios.find(s=>s.id===p.scenario),tip=nextPracticeStep(p.result,s);if(p.exam){const e=user().exam;return heading('EXAMEN',`Situación ${e.index+1} completada`,'La retroalimentación se muestra al terminar las 10 situaciones.')+`<div class="card"><h2>Conversaste con ${s.person}</h2><p>Tu respuesta quedó guardada en este dispositivo.</p><button class="btn" data-action="exam-next">${e.index===9?'Ver resultado del examen':'Siguiente situación →'}</button></div>`;}return heading('PRÁCTICA COMPLETADA','Cada conversación te enseña algo',`${s.person} · ${s.title} · ${p.difficulty}`)+`<div class="split"><section class="card"><div class="coach-next"><span class="eyebrow">PARA TU PRÓXIMO INTENTO</span><h2>${esc(tip.action)}</h2><p><strong>Una forma posible:</strong> ${esc(tip.example)}</p><p class="smallprint">Adáptalo a la conversación; hay distintas respuestas válidas.</p></div><span class="eyebrow">SEÑALES DE TU CONVERSACIÓN</span>${resultBars(p.result)}<div class="notice">Evaluación orientativa basada en patrones del texto. Una puntuación alta no garantiza una buena respuesta: revisa el contexto y los datos. Se aceptan distintas formas de responder.</div><div class="flex"><button class="btn" data-start="${s.id}">Volver a practicar</button>${link('practicar','Elegir otra situación','btn secondary')}</div></section><aside class="card"><span class="eyebrow">ÍNDICE DE PRÁCTICA</span><div class="metric">${p.result.total}<span class="muted" style="font-size:18px"> / 100</span></div><p class="muted">Úsalo para reflexionar, no como una calificación definitiva.</p><h3>Tu conversación</h3>${p.messages.map(m=>`<p style="font-size:14px"><strong>${m.role==='user'?'Tú':s.person}:</strong> ${esc(m.text)}</p>`).join('')}</aside></div>`;}
function examResults(){const e=user().exam;if(!e?.completed)return heading('EXAMEN','No hay un examen completado')+link('practicar','Volver');const average=Math.round(e.results.reduce((a,r)=>a+r.total,0)/e.results.length);return heading('EXAMEN COMPLETADO','10 situaciones. Nuevas ideas para mejorar.',`Dificultad: ${e.difficulty}`)+`<section class="card"><span class="eyebrow">PROMEDIO ORIENTATIVO</span><div class="metric">${average}/100</div><p class="muted">Estas señales ayudan a reflexionar; no son una certificación de ventas.</p>${dimensions.map((d,i)=>{const score=Math.round(e.results.reduce((a,r)=>a+r.scores[i],0)/10);return `<div class="score-row"><strong>${d}</strong><span>${score}/100</span></div><div class="progress"><span style="width:${score}%"></span></div>`;}).join('')}</section><div class="section-line"><h2>Repasa cada situación</h2></div><div class="grid">${e.results.map(r=>{const s=scenarios.find(s=>s.id===r.scenario),tip=nextPracticeStep(r,s);return `<article class="card"><h3>${s.title}</h3><span class="tag">${r.total}/100 · ${s.person}</span><p class="muted" style="font-size:14px;margin-top:16px">${r.feedback[r.scores.indexOf(Math.min(...r.scores))]}</p><p><strong>Para practicar:</strong> ${esc(tip.action)}</p></article>`;}).join('')}</div><div class="flex" style="margin-top:24px">${link('practicar','Seguir practicando')}<button class="btn secondary" data-action="exam">Nuevo examen</button></div>`;}
function opportunity(){const sections=[['Tendencia e industria','Aquí reuniremos datos de venta directa y comercio electrónico, con fuente y fecha.','Estadísticas verificadas de la industria.'],['Cómo funciona Bio4','Conocer productos, conversar con clientes y comprender las condiciones de participación.','Presentación oficial del modelo Bio4.'],['E-commerce','Revisa qué herramientas digitales ofrece Bio4 antes de explicar su alcance.','Funciones, costos y condiciones del servicio.'],['Formas de ganar','Cada forma de compensación debe explicarse con sus requisitos y condiciones.','Plan oficial de compensación vigente.'],['Comisiones','Los porcentajes y bases de cálculo se incorporarán a partir del documento oficial.','Tabla de comisiones vigente.'],['Niveles y rangos','Consulta los requisitos antes de explicar cómo se alcanza o mantiene un nivel.','Nombres, requisitos y condiciones oficiales.'],['Cómo empezar','Puedes comenzar por aprender productos y practicar conversaciones mientras revisas los requisitos de incorporación con tu asesor.','Requisitos, costos y pasos de incorporación.']];return heading('APRENDER EL NEGOCIO','Oportunidad Bio4','Una base para explicar con claridad, sin inventar cifras ni prometer ingresos.')+`<div class="notice">Contenido en preparación. Las cifras, comisiones y requisitos se agregarán cuando contemos con el material oficial vigente.</div><div class="grid">${sections.map(([t,b,need],i)=>`<section class="card"><span class="eyebrow">${String(i+1).padStart(2,'0')} · APRENDER</span><h3 style="margin-top:16px">${t}</h3><p>${b}</p><p class="smallprint">Material por incorporar: ${need}</p></section>`).join('')}</div><section class="card" style="margin-top:24px"><h3>Aprender el negocio</h3><p>Esta sección es educativa. No genera invitaciones comerciales para WhatsApp: su política restringe el marketing multinivel. Revisa el modelo y el canal antes de promocionar una oportunidad.</p><a href="https://business.whatsapp.com/policy" target="_blank" rel="noopener">Consultar política oficial</a></section>`;}
function followupGuide(){
  const replies={
    info:{label:'Pide más información',title:'Aclara qué necesita saber',body:'Pregunta qué dato le falta antes de enviar otra ficha o un texto largo.',text:'Claro. ¿Qué te gustaría conocer mejor: para qué se usa, sus ingredientes, la presentación o el precio?'},
    tiempo:{label:'Necesita tiempo',title:'Deja que decida el ritmo',body:'Ofrece una fecha solo si desea que vuelvas a escribirle.',text:'Sin problema, tómate tu tiempo. Si quieres, podemos acordar cuándo retomarlo; si prefieres no seguir, también está bien.'},
    no:{label:'No desea continuar',title:'Cierra con respeto',body:'No insistas. Marca el seguimiento como hecho y respeta su decisión.',text:'Gracias por decírmelo. No volveré a escribirte sobre este tema.'}
  };
  const item=replies[followReply]||replies.info;
  return `<section class="card follow-guide"><span class="eyebrow">CUANDO TE RESPONDAN</span><h2>Escucha antes de enviar más</h2><p class="muted">Elige la situación. Estas respuestas son ejemplos para adaptar a la conversación.</p><div class="follow-choices" role="group" aria-label="Tipo de respuesta recibida">${Object.entries(replies).map(([key,value])=>`<button class="btn secondary" data-follow-reply="${key}" aria-pressed="${key===followReply}">${value.label}</button>`).join('')}</div><div class="follow-advice"><h3>${item.title}</h3><p>${item.body}</p><div class="copy-box">${item.text}</div>${copyButton(item.text,'response_copied','seguimiento-'+followReply)}</div><p class="smallprint">Solo copia un texto si corresponde. La app no lo envía y una copia no significa que la persona haya respondido.</p></section>`;
}
function followups(){const rows=[...user().followups].sort((a,b)=>a.done-b.done||a.date.localeCompare(b.date));const text='Hola, retomo nuestra conversación como acordamos. ¿Pudiste revisar la información? Si ahora no es buen momento, dime y lo dejamos para cuando te venga bien.';return heading('ACOMPAÑA SIN INSISTIR','Seguimientos','Recuerda cuándo retomar una conversación y para qué.')+followupGuide()+`<div class="split"><section><form id="followup" class="card"><h3>Un próximo contacto</h3><div class="field"><label for="contact">Nombre o alias</label><input id="contact" name="contact" maxlength="60" required placeholder="Ej. Ana"></div><div class="field"><label for="date">Fecha acordada</label><input id="date" name="date" type="date" required></div><div class="field"><label for="note">¿Qué van a revisar?</label><input id="note" name="note" maxlength="180" placeholder="Ej. presentación y precio" required></div><label class="flex"><input class="check" type="checkbox" required name="permission"> La persona aceptó que retomáramos la conversación.</label><button class="btn" type="submit" style="margin-top:14px">Guardar seguimiento</button><p class="smallprint">Se guarda solo aquí. No se envían mensajes ni recordatorios automáticos. Evita datos sensibles.</p></form><div class="section-line"><h2>Mis conversaciones</h2></div>${rows.length?rows.map(f=>`<article class="card follow-row"><div><h3>${esc(f.contact)}</h3><p class="muted" style="margin:0">${esc(f.note)}</p><span class="tag" style="margin-top:10px">${f.done?'Completado':new Date(f.date+'T23:59:59')<new Date()?'Por retomar':'Agendado'} · ${esc(f.date)}</span></div><button class="btn small" data-follow-prepare="${f.id}" ${f.done?'disabled':''}>Preparar mensaje</button><button class="btn secondary small" data-follow-toggle="${f.id}">${f.done?'Reabrir':'Marcar hecho'}</button><button class="btn ghost small danger" data-follow-delete="${f.id}">Eliminar</button></article>`).join(''):'<div class="card empty">Todavía no tienes seguimientos. Acuerda uno y guárdalo aquí.</div>'}</section><aside class="card" style="align-self:start"><span class="eyebrow">COMPARTIR</span><h3 style="margin-top:14px">Retomar con permiso</h3><div class="copy-box">${text}</div>${copyButton(text,'response_copied','seguimiento-recordatorio')}<p class="smallprint">Adáptalo solo si ese seguimiento fue acordado.</p></aside></div>`;}
const eventLabels={product_viewed:'Productos vistos',content_copied:'Contenidos copiados',objection_viewed:'Objeciones vistas',closing_viewed:'Cierres vistos',response_copied:'Respuestas copiadas',closing_copied:'Cierres copiados',practice_started:'Prácticas iniciadas',practice_completed:'Prácticas completadas',practice_abandoned:'Prácticas sin completar',exam_completed:'Exámenes completados'};
function bars(data,scale=0){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]);const max=scale||Math.max(1,...entries.map(e=>e[1]));return entries.length?entries.map(([label,v])=>`<div class="bar-row"><span>${esc(label)}</span><div class="bar"><span style="width:${v/max*100}%"></span></div><strong>${v}</strong></div>`).join(''):'<p class="empty">Aún no hay actividad.</p>';}
function group(events,get){const result={};for(const e of events){const k=get(e);result[k]=(result[k]||0)+1;}return result;}
function admin(){const ev=db.events;const count=t=>ev.filter(e=>e.type===t).length;const complete=ev.filter(e=>e.type==='practice_completed');const copies=ev.filter(e=>['content_copied','response_copied','closing_copied'].includes(e.type));const means=Object.fromEntries(dimensions.map((d,i)=>[d,complete.length?Math.round(complete.reduce((a,e)=>a+(e.scores?.[i]||0),0)/complete.length):0]));return heading('ADMINISTRACIÓN LOCAL','Así se está usando Bio4 Socios','Actividad registrada únicamente en este navegador.')+`<div class="notice">Este panel local no tiene autenticación de administrador. No reúne datos de otros celulares. Las copias son acciones de uso: <strong>no equivalen a mensajes enviados, ventas ni afiliaciones</strong>.</div><div class="stat-grid">${[['Socios que practicaron',new Set(ev.filter(e=>e.type==='practice_started').map(e=>e.user)).size],['Prácticas completas',complete.length],['Contenidos copiados',copies.length],['Productos vistos',count('product_viewed')]].map(([t,n])=>`<section class="card"><span class="muted" style="font-size:14px">${t}</span><div class="metric">${n}</div></section>`).join('')}</div><div class="grid" style="margin-top:24px"><section class="card"><h3>Actividad</h3>${bars(Object.fromEntries(Object.entries(eventLabels).map(([k,v])=>[v,count(k)])))}</section><section class="card"><h3>Dificultad practicada</h3>${bars(group(ev.filter(e=>e.type==='practice_started'),e=>e.difficulty))}</section><section class="card"><h3>Señales por habilidad</h3><p class="smallprint">Promedio orientativo de prácticas completadas, de 0 a 100.</p>${complete.length?bars(means,100):'<p class="empty">Completa una práctica para ver las señales.</p>'}</section><section class="card"><h3>Productos más consultados</h3>${bars(group(ev.filter(e=>e.type==='product_viewed'),e=>products.find(p=>p.id===e.item)?.name||e.item))}</section><section class="card"><h3>Objeciones consultadas</h3>${bars(group(ev.filter(e=>e.type==='objection_viewed'),e=>objections.find(o=>o.id===e.item)?.title||e.item))}</section><section class="card"><h3>Escenarios practicados</h3>${bars(group(ev.filter(e=>e.type==='practice_started'),e=>scenarios.find(s=>s.id===e.scenario)?.title||e.scenario))}</section></div><section class="card" style="margin-top:24px"><h3>Guardar mi avance personal</h3><p>Para llevar tus notas, favoritos y progreso a otro equipo, usa el respaldo personal.</p>${link('respaldo','Guardar y recuperar mi avance →','btn secondary')}<h3 style="margin-top:24px">Exportar actividad</h3><p class="muted">Descarga las métricas para revisarlas fuera de este dispositivo. El archivo incluye nombres de socios y eventos; no incluye conversaciones ni seguimientos.</p><button class="btn secondary" data-action="export">Descargar métricas JSON</button><p class="smallprint">Los datos no se envían a ningún servidor. Borrar los datos del navegador elimina el progreso local.</p></section>`;}
function modal(html){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=html+'<div style="margin-top:24px"><button class="btn ghost" data-action="close-dialog">Cerrar</button></div>';document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();}
function navigate(route){if(location.hash===`#/${route}`)render();else location.hash='/'+route;}
function render(){copyTexts.clear();if(!user()){$('#app').innerHTML=login();return;}const [route,id]=(location.hash.replace(/^#\/?/,'')||'inicio').split('/');const views={inicio:home,campanas:()=>campaignPage({user,products,esc,link}),retos:()=>challengePage({user,esc,link}),respaldo:()=>backupPage({link}),historia:()=>storyPage({user,esc,link,copyButton}),favoritos:()=>favoritesPage({user,esc,link,catalog:favoriteCatalog({products,objections,closings,videos:learningVideos})}),avance:progressPage,plan:weeklyPlanPage,semana:()=>myWeekPage({user,esc,link}),secuencia:()=>sequencePage({user,esc,link,copyButton}),estados:stateGuidePage,buzon:feedbackPage,aprender:learn,lecturas:()=>booksPage({esc,link}),videos:videosPage,guias:guidesPage,equipo:teamPage,practicar:practiceList,productos:()=>id?detail(id):catalog(),compartir:()=>id?detail(id):catalog(),mas:more,objeciones:()=>library('objeciones'),cierres:()=>library('cierres'),oportunidad:opportunity,seguimientos:followups,sesion:session,examen:examResults,admin};$('#app').innerHTML=shell((views[route]||(()=>heading('BIO4 SOCIOS','Esta página no existe')+link('inicio','Volver a Inicio')))(),route);if(route==='videos'&&learningVideos.some(v=>v.id===id))requestAnimationFrame(()=>document.getElementById('video-'+id)?.scrollIntoView({block:'start'}));if(route==='secuencia'&&/^[0-7]$/.test(id||''))requestAnimationFrame(()=>document.getElementById('secuencia-paso-'+id)?.scrollIntoView({block:'start'}));if((route==='productos'||route==='compartir')&&id)readyImageButtons();if(route==='sesion'&&user().practice&&!user().practice.completed){const chat=$('.chat');if(chat)chat.scrollTop=chat.scrollHeight;}}
async function copy(k){const item=copyTexts.get(k);if(!item)return;try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(item.text);event(item.type,{item:item.id,...item.detail});toast('Texto copiado. Listo para pegar.');}catch{modal(`<h2>Copia el texto</h2><p>El navegador no permitió copiar automáticamente. Selecciona el texto y usa Copiar.</p><textarea id="manual-copy" rows="7" readonly>${esc(item.text)}</textarea>`);$('#manual-copy').select();}}
function startExam(){document.querySelector('dialog')?.close();let e=user().exam;if(e&&!e.completed){if(user().practice?.exam)navigate('sesion');else createPractice(e.ids[e.index],true);return;}if(user().practice&&!user().practice.completed){modal('<h2>Termina la práctica actual</h2><p>Puedes completarla o terminarla sin completar antes de comenzar el examen.</p>'+link('sesion','Continuar práctica'));return;}modal(`<h2>Examen de 10 situaciones</h2><p>10 conversaciones de varias rondas, sin pistas durante el examen. La retroalimentación aparece al final. Puedes salir y continuar en este navegador.</p><p><strong>Dificultad: ${practiceFilters.difficulty}</strong></p><button class="btn" data-action="exam-confirm">Comenzar examen</button>`);}
function abandon(){const p=user().practice;if(!p)return;modal(`<h2>¿Terminar sin completar?</h2><p>${p.exam?'Se cerrará este examen. Las situaciones ya completadas permanecerán en las métricas.':'Esta conversación no contará como práctica completada.'}</p><button class="btn" data-action="abandon-confirm">Sí, terminar</button>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
if(b.dataset.playVideo){const video=learningVideos.find(v=>v.id===b.dataset.playVideo);if(!video)return;const frame=document.querySelector(`[data-video-frame="${video.id}"]`);if(!frame)return;frame.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${video.id}" title="${esc(video.title)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`;return;}
if(b.dataset.guideJump){document.getElementById('guia-'+b.dataset.guideJump)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
if(b.dataset.planJump!==undefined){document.getElementById('plan-step-'+b.dataset.planJump)?.scrollIntoView({behavior:'smooth',block:'start'});return;}
if(b.dataset.weekTrack){if(!weeklyPlans[b.dataset.weekTrack])return;user().weeklyTrack=b.dataset.weekTrack;save();render();return;}
if(b.dataset.shareImage){const path=b.dataset.shareImage;const p=currentProduct();if(!p||![p.image,...(productMedia[p.id]||[]).map(c=>c.src)].includes(path))return;const open=`<a class="btn secondary" href="${path}" target="_blank" rel="noopener">Abrir imagen</a>`;if(!navigator.share){modal(`<h2>Guardar imagen</h2><p>Abre la imagen. En iPhone, mantén presionada la foto y elige guardarla en Fotos.</p>${open}`);return;}try{const file=await prepareImage(path);if(navigator.canShare&&!navigator.canShare({files:[file]})){modal(`<h2>Guardar imagen</h2><p>Este navegador no permite compartir el archivo directamente. Abre la imagen y mantenla presionada para guardarla.</p>${open}`);return;}await navigator.share({files:[file]});}catch(err){if(err?.name!=='AbortError')modal(`<h2>No se pudo abrir la hoja para compartir</h2><p>Abre la imagen y mantenla presionada para guardarla.</p>${open}`);}return;}
if(b.dataset.category){filters.category=b.dataset.category;render();return;}
if(b.dataset.shareStage){shareStage=b.dataset.shareStage;render();return;}if(b.dataset.shareVariant){shareVariant=b.dataset.shareVariant;render();return;}
if(b.dataset.shareOutcome){const p=currentProduct();if(!p||!sharingEligibility(p).enabled)return;const labels={response:'respuesta recibida',inquiry:'consulta sobre el producto',order:'pedido confirmado'};const outcome=b.dataset.shareOutcome;if(!labels[outcome])return;modal(`<h2>Registrar ${labels[outcome]}</h2><p>Para ${esc(p.name)}, variante ${shareVariant}. Confirma que ocurrió realmente y no lo habías registrado.</p><button class="btn" data-confirm-outcome="${outcome}">Confirmar registro</button>`);return;}
if(b.dataset.confirmOutcome){const p=currentProduct();if(!p||!sharingEligibility(p).enabled||!['response','inquiry','order'].includes(b.dataset.confirmOutcome))return;event('share_outcome',{item:p.id,variant:shareVariant,stage:shareStage,outcome:b.dataset.confirmOutcome});document.querySelector('dialog')?.close();render();toast('Resultado registrado; no se envió ningún mensaje.');return;}
if(b.dataset.shareUndo){const i=db.events.findIndex(e=>e.id===b.dataset.shareUndo&&e.user===db.current&&e.type==='share_outcome');if(i>=0){db.events.splice(i,1);save();render();toast('Último registro deshecho.');}return;}
if(b.dataset.action==='copy-share'){const p=currentProduct();if(!p||!sharingEligibility(p).enabled)return;const text=$('#share-editor').value.trim();if(!text){toast('Escribe un mensaje antes de copiar.');return;}shareDrafts.set(shareKey(p),text);const k=uid();copyTexts.set(k,{text,type:'content_copied',id:p.id+':'+shareStage+':'+shareVariant,detail:{product:p.id,stage:shareStage,variant:shareVariant}});await copy(k);return;}
if(b.dataset.action==='reset-share'){const p=currentProduct();if(p){shareDrafts.delete(shareKey(p));render();}return;}if(b.dataset.copy){await copy(b.dataset.copy);return;}if(b.dataset.tab){detailTab=b.dataset.tab;render();return;}if(b.dataset.openResponse){responseDialog(...b.dataset.openResponse.split(':'));return;}if(b.dataset.start){startPractice(b.dataset.start);return;}if(b.dataset.replace){const old=user().practice;event('practice_abandoned',{scenario:old.scenario,difficulty:old.difficulty,practice:old.id});document.querySelector('dialog')?.close();createPractice(b.dataset.replace);return;}if(b.dataset.followReply){if(!['info','tiempo','no'].includes(b.dataset.followReply))return;followReply=b.dataset.followReply;render();return;}if(b.dataset.followPrepare){const f=user().followups.find(f=>f.id===b.dataset.followPrepare);if(!f||f.done)return;const now=new Date();const today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');const text='Hola, como acordamos, retomo la información que querías revisar. ¿Te queda bien hablar de ello ahora? Si prefieres dejarlo aquí, lo respeto.';modal(`<h2>Preparar mensaje para ${esc(f.contact)}</h2><p><strong>Fecha acordada:</strong> ${esc(f.date)}</p><p><strong>Para revisar:</strong> ${esc(f.note)}</p>${f.date>today?'<div class="notice">La fecha acordada aún no llega. Espera, salvo que la persona te escriba primero.</div>':''}<div class="copy-box">${text}</div>${copyButton(text,'response_copied','seguimiento-personal','Copiar mensaje')}<p class="smallprint">Personaliza el mensaje antes de enviarlo. Confirma que la persona sigue de acuerdo y respeta si no desea continuar.</p>`);return;}if(b.dataset.followToggle){const f=user().followups.find(f=>f.id===b.dataset.followToggle);f.done=!f.done;save();render();return;}if(b.dataset.followDelete){modal('<h2>¿Eliminar este seguimiento?</h2><p>Se quitará de este dispositivo.</p><button class="btn" data-confirm-delete="'+b.dataset.followDelete+'">Eliminar seguimiento</button>');return;}if(b.dataset.confirmDelete){user().followups=user().followups.filter(f=>f.id!==b.dataset.confirmDelete);save();document.querySelector('dialog')?.close();render();return;}switch(b.dataset.action){case 'change-user':db.current=null;save();render();break;case 'close-dialog':document.querySelector('dialog')?.close();break;case 'reset-products':filters={q:'',category:'Todas'};render();break;case 'exam':startExam();break;case 'exam-confirm':document.querySelector('dialog')?.close();user().exam={ids:sampleExam(scenarios),difficulty:practiceFilters.difficulty,index:0,results:[],completed:false};save();createPractice(user().exam.ids[0],true);break;case 'exam-next':{const ex=user().exam;if(ex.completed){navigate('examen');break;}if(!user().practice?.completed)break;if(ex.index===9){ex.completed=true;event('exam_completed',{difficulty:ex.difficulty,score:Math.round(ex.results.reduce((a,r)=>a+r.total,0)/10)});user().practice=null;save();navigate('examen');}else{ex.index++;createPractice(ex.ids[ex.index],true);}break;}case 'abandon':abandon();break;case 'abandon-confirm':{const p=user().practice;event('practice_abandoned',{scenario:p.scenario,difficulty:p.difficulty,practice:p.id,mode:p.exam?'exam':'practice'});if(p.exam)user().exam=null;user().practice=null;save();document.querySelector('dialog')?.close();navigate('practicar');break;}case 'export':{const out={version:1,exportedAt:new Date().toISOString(),scope:'Solo este navegador; copias no equivalen a ventas',users:Object.entries(db.users).map(([id,u])=>({id,name:u.name})),events:db.events};const url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bio4-metricas-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);modal('<h2>Métricas preparadas</h2><p>Si tu navegador no inicia la descarga, puedes copiar el archivo JSON y guardarlo como texto.</p>'+copyButton(JSON.stringify(out,null,2),'metrics_export_copied','export','Copiar JSON'));break;}}});
document.addEventListener('input',e=>{if(e.target.id==='share-editor'){const p=currentProduct();if(p){shareDrafts.set(shareKey(p),e.target.value);$('#share-count').textContent=e.target.value.length+'/1500 caracteres';$('#share-review').innerHTML=shareReview(e.target.value);}return;}if(e.target.id==='product-search'){filters.q=e.target.value;$('#product-results').innerHTML=productGrid();}if(e.target.id==='reply')sessionDraft=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='share-stage'){if(e.target.value){shareStage=e.target.value;render();}return;}if(e.target.id==='category'){filters.category=e.target.value;$('#product-results').innerHTML=productGrid();}if(e.target.id==='difficulty'){practiceFilters.difficulty=e.target.value;}if(e.target.id==='topic'){practiceFilters.topic=e.target.value;render();}if(e.target.dataset.lesson!==undefined){const i=Number(e.target.dataset.lesson);user().lessons=e.target.checked?[...new Set([...user().lessons,i])]:user().lessons.filter(n=>n!==i);save();render();}if(e.target.dataset.teamStep!==undefined){const i=Number(e.target.dataset.teamStep);if(!Number.isInteger(i)||i<0||i>=teamSteps.length)return;const old=Array.isArray(user().teamSteps)?user().teamSteps:[];user().teamSteps=e.target.checked?[...new Set([...old,i])]:old.filter(n=>n!==i);save();render();}});
document.addEventListener('change',e=>{if(e.target.dataset.weekStep===undefined)return;const track=weeklyPlans[user().weeklyTrack]?user().weeklyTrack:'inicio';const i=Number(e.target.dataset.weekStep);if(!Number.isInteger(i)||i<0||i>=weeklyPlans[track].steps.length)return;const old=weekCompleted(track);if(e.target.checked)old.add(i);else old.delete(i);user().weeklyPlan={...(user().weeklyPlan||{}),[track]:[...old].sort((a,b)=>a-b)};save();render();});
document.addEventListener('change',e=>{if(e.target.dataset.stateStep===undefined)return;const i=Number(e.target.dataset.stateStep);if(!Number.isInteger(i)||i<0||i>=stateSteps.length)return;const old=new Set(Array.isArray(user().statePrep)?user().statePrep:[]);if(e.target.checked)old.add(i);else old.delete(i);user().statePrep=[...old].filter(n=>Number.isInteger(n)&&n>=0&&n<stateSteps.length).sort((a,b)=>a-b);save();render();});
document.addEventListener('submit',e=>{if(e.target.id==='login'){e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;const existing=Object.entries(db.users).find(([,u])=>normalize(u.name)===normalize(name));db.current=existing?existing[0]:uid();if(!existing)db.users[db.current]={name,lessons:[],followups:[],practice:null,exam:null};save();location.hash='/inicio';render();return;}if(e.target.id==='answer'){e.preventDefault();const p=user().practice;if(!p||p.completed)return;const text=new FormData(e.target).get('reply').trim();if(text.length<12){toast('Escribe una respuesta de al menos 12 caracteres.');return;}const s=scenarios.find(s=>s.id===p.scenario);p.responses.push(text);p.messages.push({role:'user',text});p.messages.push({role:'prospect',text:prospectReply(s,p.difficulty,p.responses)});sessionDraft='';if(shouldFinish(s,p.difficulty,p.responses)){p.completed=true;p.result=evaluate(p.responses,s);if(p.exam)user().exam.results.push({...p.result,scenario:p.scenario});event('practice_completed',{scenario:p.scenario,difficulty:p.difficulty,practice:p.id,mode:p.exam?'exam':'practice',scores:p.result.scores,score:p.result.total});}save();render();if(!p.completed)$('#reply')?.focus();return;}if(e.target.id==='followup'){e.preventDefault();const f=new FormData(e.target);const contact=f.get('contact').trim(),note=f.get('note').trim(),date=f.get('date');if(!contact||!note||!/^\d{4}-\d{2}-\d{2}$/.test(date))return;user().followups.push({id:uid(),contact,note,date,done:false});save();render();toast('Seguimiento guardado.');}});
document.addEventListener('submit',e=>{if(e.target.id!=='feedback-form')return;e.preventDefault();const form=new FormData(e.target);try{feedbackPrepared=feedbackMessage(Object.fromEntries(form));const href='https://wa.me/527299736912?text='+encodeURIComponent(feedbackPrepared);$('#feedback-result').innerHTML=`<section class="card feedback-preview"><span class="eyebrow">REVISA ANTES DE ENVIAR</span><h2>Tu reporte está listo</h2><div class="copy-box">${esc(feedbackPrepared)}</div><div class="feedback-actions"><a class="btn" href="${href}" target="_blank" rel="noopener">Abrir WhatsApp para enviarlo →</a><button class="btn secondary" type="button" data-feedback-copy>Copiar reporte</button></div><p class="smallprint">Se abrirá un chat con Ángel. El reporte solo llegará si tú pulsas Enviar en WhatsApp. También puedes editarlo allí antes de enviarlo.</p></section>`;$('#feedback-result').scrollIntoView({behavior:'smooth',block:'nearest'});}catch(err){feedbackPrepared='';toast(err.message||'Revisa el reporte.');}});
const clearFeedbackPreview=e=>{if(!e.target.closest('#feedback-form'))return;feedbackPrepared='';const result=$('#feedback-result');if(result)result.innerHTML='';};
document.addEventListener('input',clearFeedbackPreview);
document.addEventListener('change',clearFeedbackPreview);
