window.addEventListener('hashchange',()=>{document.querySelector('dialog')?.close();detailTab=location.hash.startsWith('#/compartir/')?'compartir':'aprender';sessionDraft='';feedbackPrepared='';const [r,id]=location.hash.replace(/^#\/?/,'').split('/');if(user()&&['productos','compartir'].includes(r)&&products.some(p=>p.id===id))event('product_viewed',{item:id});render();window.scrollTo(0,0);});
